using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;
using TiaMcpServer.Safety.Pipeline;
using TiaMcpServer.Worker;

namespace TiaMcpServer.Hmi;

[McpServerToolType]
public class HmiWriteTools
{
    [McpServerTool(Name = "hmi_write", ReadOnly = false, Destructive = true, OpenWorld = false,
        UseStructuredContent = true, OutputSchemaType = typeof(HmiGuardedWriteResponse))]
    [Description("Execute up to 50 ordered HMI writes (WinCC Unified; Classic WinCC through the *_classic_* operations) against one verified already-open project. Omitted dryRun or dryRun:false executes; dryRun:true previews effects, dependencies and guards. No confirmation prompt is sent. Operations: create_tag_table, update_tag_table, delete_tag_table, create_tag, update_tag, delete_tag, create_alarm, update_alarm, delete_alarm, and the screen, script and batch writes adopted from BetterTIA/writer (not live-tested; every Unified screen member outside the compile stubs is bound at runtime and fails api_member_missing with nothing changed): create_screen (screenName, optional groupPath, width, height; HmiScreenComposition.Create(name)), delete_screen (screenName, optional groupPath), rename_screens and rename_tags (renames [{ name, newName }] 1-200: screens or HMI tags by name, swaps through temporary names, one ExclusiveAccess transaction that any failure rolls back; references by name elsewhere are not changed, info guard hmi_rename_references_unverified), create_screen_item (screenName, itemName, itemType = the exact Openness type name, e.g. HmiButton, HmiIOField, HmiText, HmiRectangle, HmiCircle; optional left, top, width, height; ScreenItems.Create<T>(name), a failed geometry setter deletes the item again), delete_screen_item (screenName, itemName), set_screen_item_property (screenName, optional itemName (omitted: the screen itself), propertyName, value as text converted to exactly the runtime type of the current value: string, bool, number, enum member name, colour #RRGGBB or #AARRGGBB; a multilingual text takes culture; GetAttributeInfos writability check and read-back), set_dynamization_tag (screenName, optional itemName, propertyName, tagName: sets the Tag of the property's tag dynamization, creating one with Dynamizations.Create<TagDynamization>(propertyName) when the property has none; a script dynamization is refused), replace_in_scripts (replacements [{ find, replace }] 1-100 in one pass, longest first; optional screenName with groupPath: ScriptCode and GlobalDefinitionAreaScriptCode of every event handler, property event handler and script dynamization of the screens and their items, each read back). WinCC Unified user text lists as SimaticML files (owner request; not live-tested; the members are not documented by Siemens for Unified text lists, are bound at runtime and fail api_member_missing with nothing written or changed; info guard hmi_text_list_file_unverified): export_text_lists (directoryPath of an existing directory, optional textListNames, overwrite; one <name>.xml per user text list through HmiTextList.Export(FileInfo, ExportOptions.None) into a temporary file, staged next to the target, moved into place and hashed; system text lists and graphic lists are never exported) and import_text_lists (filePath, optional overwrite for ImportOptions.Override; HmiTextListComposition.Import of a private copy; without overwrite a new list must appear). Classic WinCC HMIs (Comfort/Advanced panels; issue #28; not live-tested; every member is documented in the V21 Siemens.Engineering.WinCC.xml and bound at runtime, api_member_missing with nothing changed when absent), classicKind tagTables|tags|screens|screenTemplates|screenPopups|screenSlideins|vbScripts|textLists|graphicLists|connections|cycles|screenGlobalElements|screenOverview; groupPath is the user folder path below the system folder, tableName the tag table of tags: export_classic_objects (classicKind, directoryPath of an existing directory, optional groupPath, tableName, objectNames, overwrite; one <name>.xml per object through Export(FileInfo, ExportOptions.None), staged, moved into place and hashed; graphic lists are never exported, V21 pitfall 3), import_classic_objects (classicKind, filePath, optional groupPath or tableName (required for tags) as the destination, overwrite for ImportOptions.Override; Import of a private copy; screens: an import whose screen number repeats or is used by another existing screen is refused before Import, V21 pitfall 4; without overwrite a new object must appear), delete_classic_object (classicKind, objectName, optional groupPath, tableName; Delete() read back gone; info guard hmi_classic_deletes), create_classic_folder and delete_classic_folder (classicKind with user folders, groupPath of the folder; Folders.Create(name) / folder Delete(), read back). WinCC Unified events and dynamizations (issue #29; not live-tested; members documented in the V21 Siemens.Engineering.WinCCUnified.xml and bound at runtime, api_member_missing with nothing changed when absent; every write is read back): set_event_script (screenName, eventType = a member of the screen or item type's event enum, e.g. Tapped, Up, Down, Loaded, scriptCode; optional groupPath, itemName (omitted: the screen), propertyName for a property event (eventType Change or QualityCodeChange), globalDefinitionAreaScriptCode, async; Find then Create of the event handler, Script.ScriptCode set), delete_event_script (screenName, eventType, optional itemName, propertyName), set_dynamization_script (screenName, propertyName, scriptCode; optional itemName, globalDefinitionAreaScriptCode, async, triggerType (Disabled, T100ms … T10s, CustomCycle, Tags, AutomaticTags), triggerTags, customDuration; Dynamizations.Create<ScriptDynamization>), set_dynamization_flashing (screenName, propertyName; optional itemName, color/alternateColor #RRGGBB or #AARRGGBB, flashingCondition Always|Never|RangeViolation, flashingRate Slow|Medium|Fast; Create<FlashingDynamization>), delete_dynamization (screenName, propertyName, optional itemName); another kind of dynamization on the property is refused (delete it first); info guard hmi_deletes_event_or_dynamization. Shapes and widgets are created with create_screen_item by their exact Openness type name and set with set_screen_item_property. WinCC Unified audit classes, runtime settings and plant objects (issue #29; not live-tested; runtime-bound like the above): create_audit_class (auditClassName; HmiAlarmAuditClassComposition.Create() then Name, a failed name deletes it again), delete_audit_class (auditClassName), set_audit_class_property (auditClassName, propertyName Name|DisplayName|CommentRequired|ConfirmationMode|RequiredFunctionRights, value, optional culture for DisplayName; info guard hmi_audit_property_unverified), set_runtime_setting (propertyName, value, optional settingsSection = a documented HmiRuntimeSetting section such as OpcUaServerRuntimeSettings or HmiReportingSettings, culture), create_plant_view / delete_plant_view (plantViewName), create_plant_view_node (plantViewName, nodeName, optional nodePath of the parent, plantObjectType for PlantViewNodeComposition.Create(name, type)), delete_plant_view_node (plantViewName, nodePath), set_plant_object_interface_property (plantViewName, nodePath, interfaceName, propertyName = a documented PlantObjectInterface property, value); the PlantViewsProvider is looked up among the services of the HMI software, then the project; deletes fire hmi_deletes_audit_class_or_plant_view. The PLC tag of an HMI tag is set with update_tag plcTag/connection. Tags use connection plus plcTag for PLC binding, or dataType for an internal tag. Alarms require alarmKind (discrete or analog). Supply multilingual text as culture/text pairs using plain text; eventText must have no line breaks and the server wraps it as markup. Never send pre-wrapped EventText. Later items may target objects created or renamed earlier in the same call. Stops on first failure without rollback or automatic replay; failed items retain appliedProperties, failedProperty and create cleanup in their typed result. TIA Portal enforces names, references and binding rules: a rejection fails the item as engineering_rejected (EngineeringTargetInvocationException) or worker_operation_failed (other Siemens exceptions) with engineeringError; portal_lost takes precedence. Completed items are verified trusted or superseded without read-back; run hmi_read validate on written tags and alarms, and compile the HMI device in TIA Portal, to find dangling references. Inspect affected objects with hmi_read before retrying. This tool never saves, downloads or controls a device.")]
    public static Task<CallToolResult> HmiWrite(OpennessWorkerClient workerClient, WriteExecution execution,
        [Description("Ordered HMI writes.")] HmiWriteOperationRequest[] operations,
        [Description("True previews without mutation; omitted or false executes.")] bool dryRun = false,
        CancellationToken cancellationToken = default)
        => execution.RunAsync(new HmiWriteDomain(workerClient), new WriteCall<HmiWriteOperationRequest>(
            operations ?? [], dryRun), cancellationToken: cancellationToken);
}
